// Explicit env: PLAYWRIGHT_MODULE, GITDASH_TEST_ORIGIN, GITDASH_TEST_OUTPUT, GITDASH_TEST_FIXTURE.
const assert=require('node:assert/strict'),fs=require('node:fs/promises');
const {chromium}=require(process.env.PLAYWRIGHT_MODULE);
(async()=>{
 const fixture=JSON.parse(await fs.readFile(process.env.GITDASH_TEST_FIXTURE,'utf8'));
 const origin=process.env.GITDASH_TEST_ORIGIN,output=process.env.GITDASH_TEST_OUTPUT;assert.ok(origin&&output);
 const browser=await chromium.launch({headless:true});const ctx=await browser.newContext({viewport:{width:1440,height:1000},permissions:['clipboard-read','clipboard-write'],timezoneId:'Asia/Tokyo'});
 const page=await ctx.newPage();page.setDefaultTimeout(20000);const errors=[],passed=[];page.on('pageerror',e=>errors.push(e.message));
 const projectUrl=tab=>`${origin}/project?path=${encodeURIComponent(fixture.path)}&tab=${tab}&range=current`;
 const download=async(scope,name)=>{const pending=page.waitForEvent('download');await scope.getByRole('button',{name,exact:true}).click();return fs.readFile(await(await pending).path());};
 const capture=async(scope,selector,name)=>{await scope.locator(selector).first().scrollIntoViewIfNeeded();await page.screenshot({path:`${output}/${name}.png`});await page.setViewportSize({width:390,height:844});await scope.locator(selector).first().scrollIntoViewIfNeeded();await page.screenshot({path:`${output}/${name}-mobile.png`});assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),`${name}: mobile overflow`);await page.setViewportSize({width:1440,height:1000});};
 await fs.mkdir(output,{recursive:true});
 try{
  await page.goto(projectUrl('files'));await page.getByRole('tab',{name:'ファイル',exact:true}).waitFor();
  const files=page.locator('.repository-files');await files.locator('summary').first().click();
  await files.getByLabel('revision',{exact:true}).fill('main');await files.getByRole('button',{name:'版のファイルを取得',exact:true}).click();await files.locator('tbody tr').first().waitFor();
  const directory=files.locator('tbody tr').filter({has:page.locator('.repository-files-path code').filter({hasText:/^src$/})});await directory.getByRole('button',{name:'開く',exact:true}).click();
  assert.ok((await files.locator('.repository-files-breadcrumbs').innerText()).includes('src'));
  await files.getByRole('searchbox').fill('example.ts');assert.equal(await files.locator('tbody tr').count(),1);await files.getByRole('button',{name:'表示',exact:true}).click();await files.locator('.repository-files-text').waitFor();assert.equal(await files.locator('.repository-files-text').innerText(),'one\ntwo\nthree\n');
  const source=await download(files,'完全なblobを保存');assert.equal(source.toString(),'one\ntwo\nthree\n');
  const historyHref=await files.getByRole('link',{name:'ファイル履歴を調べる',exact:true}).getAttribute('href');assert.ok(historyHref.includes(fixture.inspection_main)&&historyHref.includes('tab=info'));
  await capture(files,'summary','files');await files.getByRole('link',{name:'ファイル履歴を調べる',exact:true}).click();await page.waitForFunction(()=>document.querySelector('[aria-label="ファイル履歴のファイル相対パス"]')?.value==='src/example.ts');assert.equal(await page.getByLabel('ファイル履歴のリビジョン').inputValue(),fixture.inspection_main);assert.equal(await page.locator('.file-history-table').count(),0);
  await page.goto(projectUrl('files'));await files.locator('summary').first().click();await files.getByLabel('revision',{exact:true}).fill('main');await files.getByRole('button',{name:'版のファイルを取得',exact:true}).click();await files.locator('tbody tr').first().waitFor();await files.getByRole('searchbox').fill('binary.dat');await files.getByRole('button',{name:'表示',exact:true}).click();await files.locator('.repository-files-binary').waitFor();assert.deepEqual(await download(files,'完全なblobを保存'),Buffer.from([0,1,2,255]));await files.locator('summary').first().click();
  passed.push('Pinned revision tree/breadcrumbs, global path search, text and binary blob preview/download, immutable file-history handoff without execution');
  const blame=page.locator('.blame-explorer');await blame.locator('summary').first().click();await blame.getByLabel('行帰属のリビジョン').fill('feature');await blame.getByLabel('行帰属のファイル相対パス').fill(fixture.file);await blame.getByLabel('行帰属の開始行').fill('1');await blame.getByLabel('行帰属の終了行').fill('3');await blame.getByRole('button',{name:'行帰属を取得',exact:true}).click();await page.waitForFunction(()=>document.querySelectorAll('.blame-table tbody tr').length===3);
  await blame.getByLabel('取得済み行を作成者で絞り込み').selectOption({label:'Second Author'});assert.equal(await blame.locator('.blame-table tbody tr').count(),1);await blame.getByLabel('取得済み行をコミットで絞り込み').selectOption(fixture.inspection_feature);assert.ok((await blame.locator('.blame-content').innerText()).includes('second author line'));
  const csv=(await download(blame,'一致する行をCSV保存')).toString();assert.ok(csv.includes('Second Author')&&csv.includes('second author line')&&!csv.includes('UI Fixture'));
  await blame.getByRole('button',{name:'コミットを表示',exact:true}).click();await blame.locator('.blame-commit').getByText('Change one source line',{exact:true}).waitFor();await capture(blame,'summary','blame');
  await blame.getByLabel('行帰属の開始行').fill('2');await blame.getByLabel('行帰属の終了行').fill('2');await blame.getByRole('button',{name:'行帰属を取得',exact:true}).click();await page.waitForFunction(()=>document.querySelectorAll('.blame-table tbody tr').length===1);await blame.getByLabel('行帰属の終了行').fill('0');await blame.getByRole('button',{name:'行帰属を取得',exact:true}).click();await blame.getByRole('alert').first().waitFor();
  passed.push('Line attribution, exact author/commit filters, inclusive range and invalid-range error, source commit, annotated CSV');
  await page.goto(projectUrl('lanes'));const mainRow=page.locator('#project-lane-results tr').filter({has:page.locator('.lane-name-button strong').filter({hasText:/^main$/})});await mainRow.getByRole('button',{name:'Git詳細',exact:true}).click();const status=page.locator('.status-pane'),diff=page.locator('.worktree-diff');await diff.locator('.worktree-diff-snapshot').waitFor();
  const stage=status.getByRole('group',{name:'差分の段階'});await stage.getByRole('button',{name:'ステージ済み',exact:true}).click();await page.waitForFunction(()=>document.querySelector('.worktree-diff-snapshot strong')?.textContent==='ステージ済み');
  const staged=(await download(diff,'生パッチを保存')).toString();assert.ok(staged.includes('+staged line')&&!staged.includes('+working line')&&staged.includes('renamed-working.txt'));
  const sourceRow=status.locator('.status-file-row').filter({has:page.locator('.status-file-path').filter({hasText:/^src\/example\.ts$/})});await sourceRow.getByRole('button',{name:'差分を表示',exact:true}).click();await page.waitForFunction(()=>document.querySelector('.worktree-diff-snapshot')?.textContent.includes('src/example.ts'));
  await stage.getByRole('button',{name:'未ステージ',exact:true}).click();await page.waitForFunction(()=>document.querySelector('.worktree-diff-snapshot strong')?.textContent==='未ステージ');const unstaged=(await download(diff,'生パッチを保存')).toString();assert.ok(unstaged.includes('+working line')&&!unstaged.includes('+staged line'));
  await capture(diff,'.worktree-diff-heading','working-diff');
  const spaceRow=status.locator('.status-file-row').filter({has:page.locator('.status-file-path').filter({hasText:/^space\.ts$/})});await spaceRow.getByRole('button',{name:'差分を表示',exact:true}).click();await page.waitForFunction(()=>document.querySelector('.worktree-diff-snapshot')?.textContent.includes('space.ts'));
  await diff.getByRole('checkbox',{name:'空白変更を無視',exact:true}).check();await page.waitForFunction(()=>document.querySelector('.worktree-diff-snapshot')?.textContent.includes('空白変更を無視'));assert.equal((await download(diff,'生パッチを保存')).length,0);
  passed.push('Staged/unstaged snapshots and patches, per-status-file scope, rename pair preservation, ignore-whitespace control');
  assert.deepEqual(errors,[]);await fs.writeFile(`${output}/result.json`,JSON.stringify({origin,fixture:fixture.path,passed,errors},null,2));console.log({passed,errors});
 }catch(e){console.error(e);console.error(await page.evaluate(()=>({width:innerWidth,scroll:document.documentElement.scrollWidth,overflow:[...document.querySelectorAll('body *')].filter(e=>e.getBoundingClientRect().right>innerWidth+1).slice(-30).map(e=>({tag:e.tagName,cls:e.className,right:e.getBoundingClientRect().right,width:e.getBoundingClientRect().width}))})));await page.screenshot({path:`${output}/failure.png`});console.error((await page.locator('body').innerText()).slice(-2500));process.exitCode=1;}finally{await browser.close();}
})();
